var SCOPERTE=[
 {t:"Rhodiola rosea in quota: la medicina tradizionale tibetana contro l'artrite, spiegata a livello molecolare",v:"Medicina tradizionale e alta quota: uno studio retrospettivo cinese sull'artrite reumatoide in area d'altitudine mostra che l'aggiunta della Rhodiola rosea, pianta della farmacopea tradizionale tibetana, si associa a un miglior controllo dell'attività di malattia e dell'infiammazione — inclusi i segni ecografici al ginocchio — rispetto alla sola terapia convenzionale, con un possibile meccanismo legato alla via HIF-1α attivata dall'ipossia d'altitudine. Studio retrospettivo, non randomizzato, popolazione e contesto lontani dalla tua pratica: è artrite reumatoide, non artrosi. Ma è una lente raramente incontrata in ortopedia occidentale.",pmid:'42630185',doi:'10.3389/fmed.2026.1810329',temi:["mondo orientale","medicina tradizionale","artrite reumatoide"]},
 {t:"Un tutore-esoscheletro stampato in 3D per allenare la forza del ginocchio senza attrezzi",v:"Bioingegneria: un prototipo di tutore-esoscheletro per il ginocchio, stampato in 3D e a basso costo, usa bande elastiche per fornire resistenza regolabile a quadricipite e flessori in pazienti che non possono allenarsi con attrezzature tradizionali — pensato per la riabilitazione post-ictus o post-chirurgica. Studio di fattibilità su un numero limitato di partecipanti, gradimento alto su comfort e sicurezza percepita; l'efficacia clinica in pazienti reali di riabilitazione resta da dimostrare.",pmid:'42624126',doi:'10.1088/2057-1976/ae9c47',temi:["bioingegneria","riabilitazione","tecnologia indossabile"]},
 {t:"Cinque anni a misurare l'infiammazione dopo la rottura del crociato: la finestra che conta è quella subacuta",v:"Immunologia articolare: nella storica coorte svedese KANON, le concentrazioni di citochine nel liquido sinoviale misurate nelle prime settimane dopo la rottura del LCA non predicono da sole i cambiamenti di spessore cartilagineo alla RM nei due anni successivi — ma le concentrazioni misurate nella fase subacuta (mesi 4-12) sì, in particolare IL-6 e IL-10, con un'associazione che persiste fino a cinque anni. Studio esplorativo, nessuna correzione per confronti multipli dichiarata: un'ipotesi sulla finestra terapeutica per intervenire sull'infiammazione, non una dimostrazione.",pmid:'42622195',doi:'10.1016/j.ostima.2026.100410',temi:["cartilagine","immunologia","lca"]}
];